<template>
  <aside class="voice-space" aria-label="Colegio de Montalban voice assistant">
    <button class="voice-button" :class="{ listening }" type="button" :aria-expanded="open" @click="togglePanel">
      <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 15a3 3 0 0 0 3-3V6a3 3 0 0 0-6 0v6a3 3 0 0 0 3 3Zm5-3a5 5 0 0 1-10 0H5a7 7 0 0 0 6 6.92V21H8v2h8v-2h-3v-2.08A7 7 0 0 0 19 12h-2Z"/></svg>
      <span class="voice-pulse"></span><span class="sr-only">Open voice assistant</span>
    </button>
    <section v-if="open" class="voice-panel">
      <header><span class="voice-icon">AI</span><div><strong>CDM Voice Assistant</strong><small>{{ statusText }}</small></div><button class="voice-close" type="button" aria-label="Close assistant" @click="closePanel">×</button></header>
      <div ref="messagesElement" class="messages" aria-live="polite">
        <div v-for="(item,index) in messages" :key="index" class="message" :class="item.role"><span>{{ item.role==='assistant'?'CDM':'You' }}</span><p>{{ item.text }}</p></div>
        <div v-if="thinking" class="message assistant"><span>CDM</span><p class="typing">Thinking <i></i><i></i><i></i></p></div>
      </div>
      <div class="quick-actions"><button v-for="action in quickActions" :key="action.text" type="button" @click="submitMessage(action.text)">{{ action.label }}</button></div>
      <form class="assistant-input" @submit.prevent="submitMessage(input)">
        <input v-model="input" maxlength="1000" :disabled="thinking" placeholder="Ask about the system…" aria-label="Message the assistant">
        <button class="mic-button" :class="{ listening }" type="button" :disabled="!speechSupported||thinking" :title="speechSupported?'Speak':'Speech recognition is unavailable in this browser'" @click="toggleListening"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 15a3 3 0 0 0 3-3V6a3 3 0 0 0-6 0v6a3 3 0 0 0 3 3Zm5-3a5 5 0 0 1-10 0H5a7 7 0 0 0 6 6.92V21H8v2h8v-2h-3v-2.08A7 7 0 0 0 19 12h-2Z"/></svg></button>
        <button class="send-button" type="submit" :disabled="thinking||!input.trim()" aria-label="Send message">➜</button>
      </form>
      <footer><label><input v-model="speakReplies" type="checkbox"> Speak replies</label><select v-model="language" aria-label="Assistant language" @change="handleLanguageChange"><option value="en-US">English</option><option value="fil-PH">Filipino / Tagalog</option></select></footer>
    </section>
  </aside>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import api from '../utils/api.js';
const router=useRouter(),route=useRoute();
const open=ref(false),listening=ref(false),thinking=ref(false),input=ref(''),language=ref('en-US'),speakReplies=ref(true),messagesElement=ref(null);
const messages=ref([{role:'assistant',text:'Hello! I can explain the CDM career recommendation system or open a page for you. You may speak in English or Filipino.'}]);
const SpeechRecognition=typeof window!=='undefined'&&(window.SpeechRecognition||window.webkitSpeechRecognition),recorderSupported=typeof window!=='undefined'&&Boolean(navigator.mediaDevices?.getUserMedia)&&typeof MediaRecorder!=='undefined',speechSupported=Boolean(SpeechRecognition)||recorderSupported;let recognition=null,mediaRecorder=null,mediaStream=null,audioChunks=[];
const statusText=computed(()=>listening.value?'Listening…':thinking.value?'Preparing an answer…':speechSupported?'Voice and text ready':'Text ready · voice unavailable');
const quickActions=[{label:'How it works',text:'How does the system work?'},{label:'Programs',text:'What programs are available?'},{label:'Open dashboard',text:'Open the dashboard'}];
const destinations=[
  {patterns:['home','landing page'],path:'/'},{patterns:['register','registration','apply'],path:'/register'},{patterns:['login','sign in'],path:'/login'},
  {patterns:['dashboard'],path:'/dashboard'},{patterns:['profile'],path:'/profile'},{patterns:['programs','courses'],path:'/programs'},
  {patterns:['recommendation','guidance'],path:'/recommendation'},{patterns:['exam','assessment','test'],path:'/exam'},{patterns:['results','score'],path:'/results'},
  {patterns:['mobile app','download app','install app'],path:'/download-app'},
  {patterns:['location','campus map','campus address','directions','nasaan','lokasyon','saan ang school'],path:'/',hash:'location'}
];
const localAnswers = ref([]);
const refreshKnowledge = async () => {
  try { localAnswers.value = (await api.get('/assistant/knowledge')).data.topics; }
  catch { localAnswers.value = []; }
};
const togglePanel=()=>{open.value=!open.value;if(open.value)refreshKnowledge();else stopListening()};
const closePanel=()=>{open.value=false;stopListening();window.speechSynthesis?.cancel()};
const scrollMessages=async()=>{await nextTick();if(messagesElement.value)messagesElement.value.scrollTop=messagesElement.value.scrollHeight};
const addMessage=(role,text)=>{messages.value.push({role,text});scrollMessages()};
const speak=text=>{if(!speakReplies.value||!window.speechSynthesis)return;window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text.replace(/[*#`]/g,''));utterance.lang=language.value;const voices=window.speechSynthesis.getVoices();utterance.voice=voices.find(voice=>voice.lang.toLowerCase()===language.value.toLowerCase())||voices.find(voice=>language.value==='fil-PH'&&/^(fil|tl)(-|_)/i.test(voice.lang))||null;utterance.rate=1;window.speechSynthesis.speak(utterance)};
const handleLocalCommand=async message=>{const normalized=message.toLowerCase(),wantsNavigation=/\b(open|go to|show|navigate|take me|buksan|punta|ipakita)\b/.test(normalized);if(wantsNavigation){const target=destinations.find(item=>item.patterns.some(pattern=>normalized.includes(pattern)));if(target){await router.push(target.path);if(target.hash)setTimeout(()=>document.getElementById(target.hash)?.scrollIntoView({behavior:'smooth',block:'start'}),150);return target.hash?'Opening the campus location and map.':`Opening ${target.patterns[0]}.`}}await refreshKnowledge();return localAnswers.value.find(item=>item.words.some(word=>normalized.includes(word)))?.answer||null};
const submitMessage=async raw=>{const message=raw.trim();if(!message||thinking.value)return;input.value='';addMessage('user',message);stopListening();const localResponse=await handleLocalCommand(message);if(localResponse){addMessage('assistant',localResponse);speak(localResponse);return}thinking.value=true;await scrollMessages();try{const{data}=await api.post('/assistant/respond',{message,page:route.name||route.path,language:language.value});addMessage('assistant',data.message);speak(data.message)}catch(error){const fallback=error.response?.data?.message||'I cannot reach Gemini right now. You can still ask me to open a page or ask how the system works.';addMessage('assistant',fallback);speak(fallback)}finally{thinking.value=false;scrollMessages()}};
const blobToBase64=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob)});
const submitAudio=async blob=>{thinking.value=true;addMessage('user',language.value==='fil-PH'?'[Tanong gamit ang mikropono]':'[Voice question]');try{const audio=await blobToBase64(blob);const{data}=await api.post('/assistant/respond',{audio,audio_mime:blob.type.split(';')[0]||'audio/webm',page:route.name||route.path,language:language.value});addMessage('assistant',data.message);speak(data.message)}catch(error){const message=error.response?.data?.message||'I could not process that recording. Check the backend connection and try again.';addMessage('assistant',message);speak(message)}finally{thinking.value=false;scrollMessages()}};
const startRecording=async()=>{try{mediaStream=await navigator.mediaDevices.getUserMedia({audio:true});audioChunks=[];const preferred=['audio/webm;codecs=opus','audio/webm','audio/ogg'].find(type=>MediaRecorder.isTypeSupported(type));mediaRecorder=new MediaRecorder(mediaStream,preferred?{mimeType:preferred}:undefined);mediaRecorder.ondataavailable=event=>{if(event.data.size)audioChunks.push(event.data)};mediaRecorder.onstop=()=>{const blob=new Blob(audioChunks,{type:mediaRecorder?.mimeType||'audio/webm'});mediaStream?.getTracks().forEach(track=>track.stop());mediaStream=null;mediaRecorder=null;if(blob.size>0)submitAudio(blob)};mediaRecorder.start();listening.value=true}catch(error){listening.value=false;const denied=error?.name==='NotAllowedError';addMessage('assistant',denied?'Microphone permission was denied. Allow microphone access in the browser address bar, then try again.':'The microphone could not start. Use Chrome or Edge on localhost or HTTPS, or type your question.')}};
const startListening=()=>{if(!speechSupported||listening.value)return;if(language.value==='fil-PH'||!SpeechRecognition){startRecording();return}recognition=new SpeechRecognition();recognition.lang='en-US';recognition.interimResults=false;recognition.continuous=false;recognition.maxAlternatives=1;recognition.onstart=()=>{listening.value=true};recognition.onresult=event=>{input.value=event.results[0][0].transcript;submitMessage(input.value)};recognition.onerror=event=>{listening.value=false;if(event.error!=='aborted'){const errors={not_allowed:'Microphone permission was denied. Allow it in the browser address bar and try again.','not-allowed':'Microphone permission was denied. Allow it in the browser address bar and try again.','audio-capture':'No working microphone was found. Check your input device.','network':'Browser speech recognition could not reach its service. Check your internet connection.'};addMessage('assistant',errors[event.error]||`Voice recognition error: ${event.error}. Please try again or type your question.`)}};recognition.onend=()=>{listening.value=false};try{recognition.start()}catch(_){listening.value=false}};
const stopListening=()=>{if(mediaRecorder?.state==='recording'){listening.value=false;mediaRecorder.stop();return}if(recognition){recognition.abort();recognition=null}mediaStream?.getTracks().forEach(track=>track.stop());mediaStream=null;listening.value=false};const toggleListening=()=>listening.value?stopListening():startListening();
const handleLanguageChange=()=>{stopListening();addMessage('assistant',language.value==='fil-PH'?'Naka-Filipino na ako. Pindutin ang mikropono, magsalita, at pindutin itong muli kapag tapos ka na.':'English mode is active. Press the microphone and speak your question.')};
onBeforeUnmount(()=>{stopListening();window.speechSynthesis?.cancel()});
</script>

<style scoped>
.voice-space{position:fixed;right:22px;bottom:22px;z-index:80}.voice-button{position:relative;width:58px;height:58px;border:0;border-radius:50%;background:#f4d44c;color:#123b25;box-shadow:0 10px 30px rgba(8,61,36,.28);display:grid;place-items:center;cursor:pointer}.voice-button svg,.mic-button svg{width:25px;fill:currentColor}.voice-pulse{position:absolute;inset:-5px;border:1px solid rgba(244,212,76,.6);border-radius:50%;animation:pulse 2.2s infinite}.voice-button.listening{background:#e34b4b;color:#fff}.voice-button.listening .voice-pulse{border-color:#e34b4b;animation:pulse 1s infinite}.voice-panel{position:absolute;right:0;bottom:72px;width:min(390px,calc(100vw - 30px));height:min(590px,calc(100vh - 125px));background:#fff;border:1px solid #dfe7e1;box-shadow:0 18px 55px rgba(8,61,36,.24);display:flex;flex-direction:column;color:#163f29;overflow:hidden}.voice-panel>header{display:flex;align-items:center;gap:12px;padding:17px 18px;background:#0d4c2d;color:#fff}.voice-panel header div{display:flex;flex-direction:column}.voice-panel header strong{font:17px Georgia,serif}.voice-panel header small{margin-top:2px;color:#bed1c4;font-size:9px;letter-spacing:.07em;text-transform:uppercase}.voice-icon{flex:none;width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:#f4d44c;color:#123b25;font-size:11px;font-weight:900}.voice-close{margin-left:auto;border:0;background:none;color:#fff;font-size:24px;cursor:pointer}.messages{flex:1;overflow:auto;padding:18px;background:#f7f5ef}.message{margin-bottom:15px}.message span{display:block;margin-bottom:4px;color:#8d7a27;font-size:8px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.message p{display:inline-block;max-width:90%;margin:0;padding:10px 12px;background:#fff;border:1px solid #e0e5e1;font-size:12px;line-height:1.55}.message.user{text-align:right}.message.user span{text-align:right;color:#47725a}.message.user p{background:#155b37;border-color:#155b37;color:#fff;text-align:left}.typing i{display:inline-block;width:4px;height:4px;margin-left:3px;border-radius:50%;background:#7c8e82;animation:blink 1s infinite}.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}.quick-actions{display:flex;gap:6px;padding:9px 12px;overflow-x:auto;border-top:1px solid #e6e9e6}.quick-actions button{flex:none;border:1px solid #cbd7ce;background:#fff;color:#205e3a;padding:7px 9px;font-size:9px;font-weight:800;cursor:pointer}.assistant-input{display:grid;grid-template-columns:1fr 38px 38px;gap:6px;padding:10px 12px;border-top:1px solid #e6e9e6}.assistant-input input{min-width:0;border:1px solid #cfd8d1;padding:10px;font:12px inherit;outline:none}.assistant-input input:focus{border-color:#1b6b42}.mic-button,.send-button{border:0;display:grid;place-items:center;cursor:pointer}.mic-button{background:#edf3ef;color:#185d39}.mic-button svg{width:18px}.mic-button.listening{background:#e34b4b;color:#fff}.send-button{background:#155b37;color:#fff;font-size:18px}.mic-button:disabled,.send-button:disabled{opacity:.45;cursor:not-allowed}.voice-panel>footer{display:flex;align-items:center;justify-content:space-between;padding:9px 13px;background:#f3f4f0;color:#607068;font-size:10px}.voice-panel footer label{display:flex;align-items:center;gap:6px}.voice-panel footer select{border:1px solid #ced7d0;background:#fff;padding:4px;color:#345442;font-size:10px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@keyframes pulse{0%,100%{transform:scale(.96);opacity:.8}50%{transform:scale(1.12);opacity:0}}@keyframes blink{0%,100%{opacity:.25}50%{opacity:1}}@media(max-width:700px){.voice-space{right:14px;bottom:14px}.voice-button{width:54px;height:54px}.voice-panel{height:min(560px,calc(100vh - 105px))}}
</style>
